SELECT 'all 26 vessels are in and cite Triax 2' AS assertion, count(*) AS got, 26 AS want
  FROM vehicles WHERE source_book LIKE 'Rifts World Book 31: Triax 2 p.%' AND slug IN ('triax-commercial-sdc-automobile', 'triax-luxury-sdc-sedan', 'triax-sports-car', 'triax-compact-car', 'triax-motorcycle', 'triax-motor-scooter', 'triax-pickup-truck', 'triax-jeeps-and-suvs', 'triax-cargo-van', 'triax-commercial-bus', 'triax-armored-security-vehicle', 'triax-16-wheel-cargo-truck-and-trailer', 'triax-hovercycle', 'triax-a-type-hover-car', 'triax-z-type-luxury-hover-sedan', 'triax-s-type-hover-sports-car', 'triax-b-type-hover-work-vehicle', 'wr-3030-bear-all-terrain-vehicle', 'rrk-oberteil-armored-hovercar', 'rrk-super-armored-hover-truck', 'waffentek-blitzschnell', 'triax-v-100-housekeeper', 'triax-v-200-robot-chauffeur', 'triax-v-250-landscaper-farm-worker', 'triax-v-1000-personal-assistant-bot', 'triax-v-500-robot-pet');
